-- Copier-coller ce fichier ENTIER dans Supabase SQL Editor -> Run
--
-- PREREQUIS : uploader l'affiche dans Storage AVANT d'executer ce script
--   Studio -> Storage -> bucket 'admin-events'
--   -> creer le dossier 'bachata-javisones'
--   -> uploader bachatta.png sous le nom 'poster-2026-2027.png'
--   URL publique attendue : https://dpqxefmwjfvoysacwgef.supabase.co/storage/v1/object/public/admin-events/bachata-javisones/poster-2026-2027.png
--
-- Idempotent : peut etre relance sans creer de doublons (ON CONFLICT identifiant)
-- ============================================================

on conflict (identifiant) do update set
  nom_de_la_manifestation = excluded.nom_de_la_manifestation,
  descriptif_court = excluded.descriptif_court,
  descriptif_long = excluded.descriptif_long,
  horaires = excluded.horaires,
  lieu_nom = excluded.lieu_nom,
  lieu_adresse_2 = excluded.lieu_adresse_2,
  code_postal = excluded.code_postal,
  commune = excluded.commune,
  ville = excluded.ville,
  reservation_site_internet = excluded.reservation_site_internet,
  photo_url = excluded.photo_url;
